function _R(s) {
  const e = new Map(s.map(a => [a.id, a]));
  const t = Gb.map(a => {
    const r = e.get(a.id);
    if (!r) {
      return a;
    }
    const r_payload = r.payload;
    return {
      ...a,
      title: r_payload.title,
      english: r_payload.english,
      summary: r_payload.summary,
      scope: r_payload.scope,
      clinicalContent: r_payload.clinicalContent,
      flow: r_payload.flow,
      tables: r_payload.tables || [],
      references: r_payload.references,
      articleDetail: r_payload.detail,
      illustrations: r_payload.illustrations || [],
      version: `0.6 · ${r.version}`,
      updatedAt: new Date(r.published_at).toLocaleDateString("ru-RU"),
      status: "draft",
      review: {
        author: null,
        reviewer: null,
        checkedAt: null,
        approvedBy: null
      }
    };
  });
  xt.splice(0, xt.length, ...t);
}

