const ro = s => {
  switch (s) {
    case "pediatric":
      return "Дети";
    case "adult":
      return "Взрослые";
    default:
      return "Все пациенты";
  }
};

const normalizeSearch = s => s.toLocaleLowerCase("ru").replace(/ё/g, "е").trim();

function eD(s, e = "all") {
  const t = normalizeSearch(s).split(/\s+/).filter(Boolean);
  if (!t.length) {
    return [];
  }
  const a = r => t.every(o => normalizeSearch(r).includes(o));
  return [...xt.filter(r => (e === "all" || r.age === e) && a([r.title, r.english, ...r.keywords].join(" "))).map(r => ({
    id: r.id,
    title: r.title,
    subtitle: `${ro(r.age)} · ${Yl[r.status]}`,
    path: `/protocol/${r.id}`,
    type: "protocol"
  })), ...ql.filter(r => (e === "all" || r.ageGroups.includes(e)) && a(`${r.title} ${r.summary}`)).map(r => ({
    id: r.id,
    title: r.title,
    subtitle: "Раздел · материалы в подготовке",
    path: `/system/${r.id}?age=${e}`,
    type: "system"
  }))];
}

const tD = JSON.parse('[{"id":"chest-pain","title":"Боль в грудной клетке","english":"Chest pain","ages":["adult","pediatric"],"group":"symptoms","clinical":"Боль оценивают по началу, локализации, связи с дыханием, нагрузкой и положением тела. Болезненность при пальпации поддерживает мышечно-скелетную причину, но сама по себе не исключает опасное заболевание.","causes":[["Острый коронарный синдром","Давящая боль, нагрузка, потливость; возможна атипичная картина."],["ТЭЛА или пневмоторакс","Внезапная боль с одышкой; оценить факторы риска и асимметрию дыхания."],["Плеврит / мышечная боль","Связь с кашлем и движением; диагноз после оценки опасных причин."]],"danger":"Обморок, гипотензия, выраженная одышка, новая аритмия или внезапная максимальная боль требуют экстренной оценки.","diagnostics":"У взрослых при подозрении на ишемию — ранняя ЭКГ и серийный тропонин по принятому маршруту. Снимок грудной клетки, УЗИ и КТ назначают по предполагаемой причине; единичная нормальная ЭКГ не исключает ОКС.","treatment":"Обезболивание и помощь по ABCDE проводят параллельно обследованию. Кислород нужен при гипоксемии. Антикоагуляцию или другую специфическую терапию выбирают после оценки диагноза и противопоказаний.","routing":"Нестабильность или подозрение на сосудистую катастрофу — экстренный стационар. Выписка допустима после обоснованного исключения опасных причин и с планом повторного обращения.","scenario":"Пациент сообщает о внезапной боли на вдохе и одышке после длительной поездки. Давление сохранено. Какие опасные причины нужно исключить до диагноза «межрёберная невралгия»?","images":["Схема локализации боли и основных опасных причин","Примеры ЭКГ и рентгенограмм с клиническими пояснениями"],"source":"chest","pediatric":"У ребёнка уточнить связь с нагрузкой, обморок, сердцебиение и семейную внезапную смерть. ЭКГ и визуализация определяются риском; взрослые шкалы ОКС и ТЭЛА не переносят автоматически."},{"id":"pediatric-respiratory-failure","title":"Дыхательный дистресс и недостаточность у детей","english":"Respiratory distress and failure in children","ages":["pediatric"],"group":"critical","clinical":"Дистресс означает повышенную работу дыхания; недостаточность — неспособность обеспечить газообмен. При истощении втяжения могут уменьшаться, хотя состояние ухудшается. Оценить PAT, затем ABCDE с учётом возраста.","causes":[["Верхняя обструкция","Стридор, изменённый голос, затруднённый вдох."],["Нижняя обструкция или поражение лёгких","Свист, удлинённый выдох либо хрипы и гипоксемия."],["Недостаточный дыхательный драйв","Редкое поверхностное дыхание, апноэ, нарушение сознания."]],"danger":"Апноэ, брадикардия, слабый воздушный поток, истощение и нарушение сознания требуют немедленной поддержки вентиляции.","diagnostics":"Пульсоксиметрия с проверкой сигнала; газы крови и CO₂ при подозрении на гиповентиляцию. Визуализация по клинике после начала стабилизации. Нормальная SpO₂ на кислороде не исключает гиперкапнию.","treatment":"Обеспечить проходимость дыхательных путей, кислород и эффективную вентиляцию по необходимости. При неэффективном дыхании начать вентиляцию мешком с маской; одновременно лечить установленную причину и привлечь реанимационную команду.","routing":"Апноэ, нарастающая поддержка или нарушение перфузии — ОРИТ. Новорождённым нужен отдельный неонатальный маршрут и оборудование.","scenario":"Младенец с инфекцией стал вялым: втяжения уменьшились, дыхание стало редким. Это улучшение или истощение?","images":["Четыре клинических механизма дыхательных нарушений у ребёнка","Фото-примеры втяжений и положения при дыхательном дистрессе"],"source":"pediatric-failure","pediatric":""},{"id":"airway-obstruction","title":"Обструкция дыхательных путей","english":"Airway obstruction","ages":["adult","pediatric"],"group":"critical","clinical":"Обструкция бывает частичной и полной. Стридор указывает на сужение верхних дыхательных путей; отсутствие звука при невозможности говорить или кашлять может означать критическое уменьшение потока.","causes":[["Инородное тело","Внезапное поперхивание во время еды или игры."],["Отёк / анафилаксия","Связь с аллергеном, отёк губ или языка, возможны гипотензия и бронхоспазм."],["Инфекция / структурное поражение","Лихорадка, дисфагия, слюнотечение или постепенно меняющийся голос."]],"danger":"Неэффективный кашель, невозможность говорить, цианоз, угнетение сознания или быстро нарастающий отёк — немедленная помощь.","diagnostics":"Сначала оценить голос, кашель, движение воздуха и сознание. При тяжёлой обструкции визуализация не должна задерживать помощь. Осмотр и инструментальную оценку планируют с командой дыхательных путей.","treatment":"Сохранить положение комфорта и вызвать помощь. При инородном теле применять соответствующий возрасту алгоритм; не выполнять слепое удаление пальцем. При анафилаксии приоритетен внутримышечный адреналин по действующему протоколу.","routing":"Прогрессирующая обструкция требует места с возможностью немедленного обеспечения дыхательных путей. После устранения причины оценить остаточные симптомы и потребность в наблюдении.","scenario":"После укуса насекомого появились осиплость и отёк языка. Нельзя ждать результата снимка, прежде чем начать помощь.","images":["Схема уровней обструкции: гортань, трахея, бронхи","Возрастные приёмы помощи при инородном теле"],"source":"airway","pediatric":"У ребёнка минимизировать плач и ненужные манипуляции. При подозрении на эпиглоттит не проводить насильственный осмотр глотки и не укладывать против воли."},{"id":"dyspnea","title":"Одышка","english":"Dyspnea","ages":["adult","pediatric"],"group":"symptoms","clinical":"Одышка — симптом, а не диагноз. Уточнить внезапное или постепенное начало, связь с нагрузкой и положением лёжа, кашель, боль, лихорадку, отёки, кровопотерю и лекарства.","causes":[["Лёгочные причины","Обструкция, инфекция, пневмоторакс или тромбоэмболия."],["Сердечные причины","Застой, аритмия, ишемия или клапанная патология."],["Внелёгочные причины","Анемия, ацидоз, нервно-мышечная слабость; тревога после исключения опасных причин."]],"danger":"Неспособность говорить фразами, истощение, низкая сатурация, гипотензия и изменённое сознание — признаки высокой срочности.","diagnostics":"Оценить частоту дыхания, SpO₂, пульс и давление. ЭКГ, рентгенография, УЗИ, общий анализ крови и газы крови выбираются по клинической гипотезе. Нормальная сатурация не исключает ТЭЛА или анемию.","treatment":"Положение по переносимости; кислород при гипоксемии и вентиляционная поддержка при неэффективном дыхании. Бронходилататор, диуретик или иное лечение назначают при соответствующем механизме, а не при любой одышке.","routing":"Нестабильность — экстренная госпитализация. При стабильном состоянии нужен установленный рабочий диагноз, оценка при нагрузке по показаниям и понятный план наблюдения.","scenario":"Одышка сопровождается нормальной SpO₂, тахикардией и болью на вдохе. Можно ли считать причиной только тревогу?","images":["Схема дифференциальной диагностики острой одышки","Пример УЗИ лёгких: A-линии, B-линии и консолидация"],"source":"dyspnea","pediatric":"У детей учитывать возрастную частоту дыхания, кормление и работу дыхания. Для младенца отказ от еды может быть ранним признаком ухудшения."},{"id":"cough","title":"Кашель","english":"Cough","ages":["adult","pediatric"],"group":"symptoms","clinical":"Уточнить длительность, сухой или влажный характер, ночные симптомы, связь с едой, инфекцией, курением и препаратами. Цвет мокроты сам по себе не доказывает бактериальную инфекцию.","causes":[["Острая инфекция","Ринит, лихорадка, контакт; исключить пневмонию при тяжёлом течении."],["Хронические причины","Астма, заболевания верхних дыхательных путей, рефлюкс; у взрослых — также ингибиторы АПФ."],["Опасные альтернативы","Аспирация, туберкулёз, опухоль, сердечная недостаточность."]],"danger":"Кровохарканье, гипоксемия, выраженная одышка, потеря массы, стойкая лихорадка или внезапное начало после поперхивания требуют дообследования.","diagnostics":"Осмотр и пульсоксиметрия; рентгенография при тревожных признаках и стойких симптомах. Спирометрия по возрасту и клинике. При риске туберкулёза — инфекционный маршрут и соответствующие тесты.","treatment":"Лечить причину, обеспечить питьё по переносимости и исключить дым. Антибиотик не назначают автоматически. Избегать одновременного бесконтрольного применения средств, подавляющих кашель, и препаратов для отхождения мокроты.","routing":"Стабильному пациенту — наблюдение с конкретным сроком повторной оценки. Нарастание одышки, кровь или системное ухудшение требуют срочного обращения.","scenario":"Три недели кашля после ОРВИ, но теперь появились ночная потливость и снижение массы. Нужно пересмотреть первоначальный диагноз.","images":["Карта причин кашля по длительности и сопутствующим симптомам","Схема различий сухого и влажного кашля без привязки к торговым препаратам"],"source":"cough","pediatric":"У ребёнка ежедневный кашель более 4 недель требует отдельной оценки. Влажный кашель и повторные пневмонии не следует автоматически объяснять астмой; взрослые противокашлевые схемы не подходят младенцам."},{"id":"wheezing","title":"Свистящее дыхание","english":"Wheezing","ages":["adult","pediatric"],"group":"symptoms","clinical":"Экспираторный свист связан с ограничением воздушного потока. Диффузный двусторонний свист и односторонний локальный шум имеют разный диагностический смысл; отличать их от инспираторного стридора.","causes":[["Астма / ХОБЛ","Повторные эпизоды и характерный анамнез."],["Инородное тело","Внезапный или стойкий односторонний свист."],["Другие причины","Анафилаксия, сердечная недостаточность, инфекция или сдавление бронха."]],"danger":"«Немое лёгкое», истощение, нарушение сознания, выраженная гипоксемия или анафилаксия требуют немедленной помощи.","diagnostics":"Уточнить триггер и оценить симметрию дыхания. Пульсоксиметрия; спирометрия после стабилизации по возрасту. Снимок при фокальных признаках, боли или нетипичном течении.","treatment":"При бронхоспазме использовать ингаляционный бронходилататор с проверкой доставки. Отсутствие эффекта требует пересмотра причины; при анафилаксии бронходилататор не заменяет адреналин.","routing":"Первый тяжёлый эпизод, асимметрия или неполный ответ — профильная оценка. При повторных эпизодах нужен план диагностики и контроля заболевания.","scenario":"Свист справа не исчез после ингаляции, а симптомы начались во время еды. Нужно вернуться к версии аспирации.","images":["Схема различий стридора и экспираторного свиста","Сравнение диффузного и одностороннего ограничения воздушного потока"],"source":"wheeze","pediatric":"У младенца первый эпизод на фоне насморка чаще связан с бронхиолитом. У дошкольника повторный свист оценивают по отдельной возрастной схеме."},{"id":"hemoptysis","title":"Кровохарканье","english":"Hemoptysis","ages":["adult","pediatric"],"group":"symptoms","clinical":"Уточнить, действительно ли кровь поступает из дыхательных путей: исключить носоглоточное кровотечение и рвоту кровью. Опасность определяется угрозой проходимости дыхательных путей и газообмену, а не только оценённым объёмом.","causes":[["Инфекция / бронхоэктазы","Мокрота, лихорадка, хронический продуктивный кашель."],["Сосудистое поражение","ТЭЛА, васкулит или диффузное альвеолярное кровотечение."],["Опухоль / туберкулёз","Факторы риска, системные симптомы и повторные эпизоды."]],"danger":"Продолжающаяся кровь с удушьем, падением сатурации или давления — жизнеугрожающее кровотечение.","diagnostics":"Общий анализ крови, коагуляция, группа крови по тяжести; рентгенография, КТ-ангиография и бронхоскопия по состоянию. Уточнить антикоагулянты и нарушения гемостаза.","treatment":"Вызвать команду, обеспечить оксигенацию и отсасывание по необходимости. При известной стороне кровотечения и сохранённом дыхании обычно размещают поражённой стороной вниз; окончательная тактика зависит от проходимости дыхательных путей. Обсудить эмболизацию и коррекцию коагулопатии.","routing":"Жизнеугрожающее кровохарканье — ОРИТ и специализированный центр. Даже небольшое повторное кровохарканье требует выяснения причины.","scenario":"Пациент с бронхоэктазами откашливает кровь и начинает захлёбываться. Приоритет — защита дыхательных путей, а не точный подсчёт миллилитров.","images":["Схема отличий кровохарканья, носоглоточного кровотечения и гематемезиса","КТ-пример источника кровотечения и схема бронхиальных артерий"],"source":"hemoptysis","pediatric":"У ребёнка кровохарканье встречается реже: проверить носоглотку, инфекцию и аспирацию. Требуется педиатрическая оценка; не использовать взрослые пороговые объёмы."},{"id":"foreign-body-adult","title":"Аспирация инородного тела у взрослых","english":"Foreign body aspiration","ages":["adult"],"group":"critical","clinical":"Возможны внезапное поперхивание, кашель, дисфония и одностороннее ослабление дыхания. У пациентов с дисфагией или неврологическими заболеваниями эпизод может быть незамеченным.","causes":[["Верхняя обструкция","Неэффективный кашель, невозможность говорить или дышать."],["Бронхиальное инородное тело","Локальный свист, ателектаз, повторная инфекция."],["Альтернатива","Анафилаксия, острый отёк гортани или приступ астмы."]],"danger":"Невозможность говорить, неэффективный кашель и потеря сознания требуют немедленного алгоритма помощи при удушье.","diagnostics":"После стабилизации — рентгенография и консультация для бронхоскопии. Невидимый на снимке органический объект не исключён. Обследование не должно задерживать помощь при полной обструкции.","treatment":"При эффективном кашле поощрять его и наблюдать. При тяжёлой обструкции у сознательного взрослого — действующий алгоритм ударов по спине и толчков с учётом беременности и телосложения; при утрате сознания — СЛР. Не выполнять слепой поиск пальцем.","routing":"Сохраняющееся подозрение требует профильной оценки и решения о бронхоскопии. После успешных приёмов проверить травмы и остаточную обструкцию.","scenario":"После еды сохраняется локальный свист; рентгенограмма без видимого предмета. Нужна ли дальнейшая оценка?","images":["Схема помощи взрослому при частичной и тяжёлой обструкции","Пример непрямых рентгенологических признаков бронхиального инородного тела"],"source":"fba-adult","pediatric":""},{"id":"respiratory-failure","title":"Дыхательная недостаточность и остановка дыхания","english":"Respiratory failure and arrest","ages":["adult"],"group":"critical","clinical":"Различают недостаточную оксигенацию и недостаточную вентиляцию; оба механизма могут сочетаться. Сонливость при поверхностном дыхании может означать гиперкапнию, даже если кислород поддерживает сатурацию.","causes":[["Гипоксемическая","Пневмония, отёк, ОРДС, шунтирование."],["Гиперкапническая","Обструкция, угнетение дыхательного центра, нервно-мышечная слабость."],["Остановка дыхания","Нет эффективного дыхания; немедленно проверить признаки кровообращения."]],"danger":"Апноэ, истощение, незащищённые дыхательные пути, шок и ухудшение сознания требуют реанимационной команды.","diagnostics":"Газы крови с pH и PaCO₂, пульсоксиметрия, ЭКГ и визуализация по причине. Проверять оборудование, подачу кислорода и проходимость дыхательных путей.","treatment":"Начать поддержку дыхания одновременно с поиском причины. При апноэ и сохранённом кровообращении нужна вентиляция; при остановке кровообращения — СЛР. Неинвазивная поддержка подходит не всем; при незащищённых дыхательных путях или неэффективности нужен инвазивный контроль.","routing":"Прогрессирующая дыхательная недостаточность требует мониторируемого отделения или ОРИТ. Оценивать ответ сразу после каждого изменения поддержки.","scenario":"Сонливость после седативного препарата, редкое дыхание и высокая SpO₂ на кислороде: почему одной сатурации недостаточно?","images":["Схема гипоксемической и гиперкапнической недостаточности","Последовательность выбора респираторной поддержки"],"source":"failure","pediatric":""},{"id":"ards","title":"Острый респираторный дистресс-синдром","english":"Acute respiratory distress syndrome","ages":["adult","pediatric"],"group":"critical","clinical":"ОРДС — острое воспалительное повреждение лёгких с гипоксемией и двусторонними изменениями после известного повреждающего события. Картина не должна полностью объясняться сердечной недостаточностью или перегрузкой жидкостью.","causes":[["Прямое повреждение","Пневмония, аспирация, ингаляционная травма."],["Непрямое повреждение","Сепсис, тяжёлая травма, панкреатит."],["Похожие состояния","Кардиогенный отёк, альвеолярное кровотечение, интерстициальное поражение."]],"danger":"Растущая потребность в кислороде, утомление, нестабильность и нарушение сознания требуют ранней интенсивной терапии.","diagnostics":"Оценить газообмен с учётом вида поддержки, рентгенографию или КТ, сердце и водный баланс. Степень тяжести определяют по актуальным критериям, а не только по виду снимка.","treatment":"Лечить причину и поддерживать оксигенацию. В ОРИТ — протективная вентиляция, индивидуальное PEEP и положение на животе по показаниям. После коррекции шока избегать избыточного положительного водного баланса.","routing":"При прогрессировании необходим ОРИТ; рефрактерная гипоксемия требует обсуждения специализированных методов поддержки.","scenario":"После сепсиса появились двусторонние затемнения и нарастающая гипоксемия. Какие данные помогут отличить ОРДС от кардиогенного отёка?","images":["Сравнение ОРДС и кардиогенного отёка на визуализации","Схема протективной вентиляции без фиксированных настроек для всех пациентов"],"source":"ards","pediatric":"Для детей используют педиатрические критерии PARDS и соответствующие индексы оксигенации. Взрослые пороги и настройки не переносят автоматически."},{"id":"asthma","title":"Бронхиальная астма","english":"Asthma","ages":["adult","pediatric"],"group":"obstructive","clinical":"Для астмы характерны вариабельные эпизоды свиста, кашля, стеснения в груди и одышки. Диагноз подтверждают сочетанием характерной истории и объективной вариабельности ограничения потока, когда это возможно.","causes":[["Типичные триггеры","Вирусы, аллергены, нагрузка, дым, профессиональные воздействия."],["Похожие состояния","Дисфункция гортани, аспирация, ХОБЛ, сердечная недостаточность."],["Причины плохого контроля","Неверная техника, нерегулярный приём, продолжающееся воздействие триггера."]],"danger":"Тяжёлый приступ, предыдущая интубация, частые обострения или нарастающая потребность в препарате облегчения повышают риск.","diagnostics":"Спирометрия с оценкой обратимости по возрасту; при необходимости дневник пиковой скорости выдоха и повторное обследование. Нормальный тест вне симптомов не всегда исключает астму.","treatment":"Долгосрочная терапия должна включать противовоспалительный компонент по возрастной схеме. Проверить технику ингаляции, приверженность, триггеры и письменный план действий. При остром ухудшении перейти к странице приступа.","routing":"Плановые контрольные визиты оценивают симптомы и риск обострений. Неэффективность терапии после проверки техники требует пересмотра диагноза и консультации.","scenario":"Ночные симптомы сохраняются при назначенном ингаляторе. Что проверить перед механическим повышением ступени лечения?","images":["Схема вариабельной бронхиальной обструкции","Пошаговая техника ингалятора и спейсера"],"source":"asthma","pediatric":"Страница для детей школьного возраста. Дошкольники вынесены отдельно: подтвердить обструкцию спирометрией у них часто невозможно, а выбор устройства зависит от координации."},{"id":"acute-asthma-adult","title":"Обострение бронхиальной астмы у взрослых","english":"Acute asthma exacerbation","ages":["adult"],"group":"obstructive","clinical":"Острое усиление одышки, кашля и свиста требует оценки речи, дыхательного усилия, воздушного потока и прежних тяжёлых эпизодов. Тихая грудная клетка у истощённого пациента — опасный признак.","causes":[["Тяжёлый приступ","Короткая речь, выраженное усилие и плохой поток."],["Альтернативный диагноз","Анафилаксия, пневмоторакс, ТЭЛА или сердечная недостаточность."],["Проблемы доставки","Пустой ингалятор, плохая техника, отсутствие спейсера."]],"danger":"Сонливость, истощение, «немое лёгкое», нарастающая гиперкапния или нестабильность требуют немедленного привлечения ОРИТ.","diagnostics":"SpO₂ и пиковая скорость выдоха при возможности без задержки помощи. Газы крови при тяжёлом течении; снимок при осложнениях или нетипичной картине, не рутинно каждому.","treatment":"Повторная ингаляционная бронходилатация, кислород при гипоксемии и ранний системный ГКС по действующему взрослому протоколу. При тяжёлом течении добавить ипратропий; при недостаточном ответе обсудить внутривенный магний и дальнейшую поддержку.","routing":"Отсутствие устойчивого ответа — госпитализация. Перед выпиской нужны стабильность, противовоспалительная терапия, проверка техники, план действий и ранний контроль.","scenario":"После нескольких ингаляций пациент стал тише и сонливее, а поток воздуха уменьшился. Это не критерий улучшения.","images":["Схема оценки тяжести приступа у взрослого","Сравнение нормальной аускультации, свиста и «немого лёгкого»"],"source":"acute-asthma","pediatric":""},{"id":"copd-exacerbation","title":"Обострение ХОБЛ","english":"Acute exacerbation of COPD","ages":["adult"],"group":"obstructive","clinical":"Обострение проявляется усилением одышки, кашля и/или изменением мокроты сверх обычной вариабельности. Инфекция — частая причина, но необходимо исключить пневмонию, отёк лёгких, ТЭЛА и пневмоторакс.","causes":[["Инфекционное обострение","Новая мокрота, гнойность, лихорадка по клинике."],["Гиперкапническая недостаточность","Сонливость, ацидоз и рост PaCO₂."],["Альтернативная причина","Боль, асимметрия дыхания, отёки или факторы риска тромбоза."]],"danger":"Нарушение сознания, ацидоз, выраженное усилие, гипоксемия и нестабильность требуют мониторируемой помощи.","diagnostics":"Пульсоксиметрия, газы артериальной крови при госпитальной оценке, рентгенография и ЭКГ. Посев мокроты — по тяжести и риску резистентности.","treatment":"Ингаляционные бронходилататоры и короткий курс системного ГКС по протоколу. При риске гиперкапнии обычно целятся в SpO₂ 88–92% с контролем газов. Антибиотик по признакам бактериального обострения и тяжести. Сохраняющийся гиперкапнический ацидоз после начальной терапии — оценка для НИВ.","routing":"Нарастающая недостаточность — ОРИТ. После стабилизации пересмотреть ингаляторы, кислород, курение, реабилитацию и план раннего повторного визита.","scenario":"У пациента с ХОБЛ после бесконтрольного кислорода появилась сонливость. Следует проверить газовый состав и вентиляцию.","images":["Схема контролируемой кислородотерапии при риске гиперкапнии","Алгоритм оценки необходимости НИВ"],"source":"copd","pediatric":""},{"id":"exercise-bronchoconstriction","title":"Бронхоконстрикция, вызванная нагрузкой","english":"Exercise-induced bronchoconstriction","ages":["adult","pediatric"],"group":"obstructive","clinical":"Кашель, свист и стеснение после нагрузки могут отражать бронхоконстрикцию, но жалобы сами по себе её не подтверждают. Уточнить время появления и исчезновения симптомов, аллергию и контроль астмы.","causes":[["Бронхоконстрикция","Экспираторные симптомы, нередко после окончания нагрузки."],["Индуцируемая обструкция гортани","Преимущественно шумный вдох на пике нагрузки."],["Другие причины","Детренированность, анемия, сердечное заболевание."]],"danger":"Обморок, боль на нагрузке, выраженное удушье или гипоксемия требуют исключения опасной причины.","diagnostics":"Спирометрия и объективная нагрузочная или иная бронхопровокационная проба в соответствующем центре. Оценить различия между бронхиальными и гортанными симптомами.","treatment":"Оптимизировать базисную терапию астмы; обсудить препарат перед нагрузкой в рамках индивидуального плана. Разминка и снижение воздействия холодного сухого воздуха могут уменьшить симптомы. Физическую активность сохраняют при адекватном контроле.","routing":"Повторные симптомы несмотря на лечение — пересмотр диагноза и консультация пульмонолога. Экстренное течение ведут как острый приступ.","scenario":"У спортсмена шумный вдох начинается на пике бега и быстро проходит после остановки. Стоит проверить гортанный механизм.","images":["Сравнение временного профиля бронхоконстрикции и обструкции гортани","Пример кривых спирометрии до и после нагрузки"],"source":"exercise","pediatric":"У детей нагрузочные жалобы обсуждают вместе с переносимостью игры, школьной физкультуры и техникой ингаляции. Обморок на нагрузке требует отдельной оценки."},{"id":"bronchiectasis","title":"Бронхоэктазы","english":"Bronchiectasis","ages":["adult","pediatric"],"group":"chronic","clinical":"Необратимое расширение бронхов связано с нарушением очищения и повторным воспалением. Типичны хронический влажный кашель, мокрота, рецидивы инфекции; возможны кровохарканье и одышка.","causes":[["После инфекции","Тяжёлая перенесённая инфекция или повторная аспирация."],["Системная причина","Муковисцидоз, иммунодефицит, нарушение работы ресничек."],["Обструкция","Инородное тело или эндобронхиальное поражение."]],"danger":"Значимое кровохарканье, гипоксемия, сепсис или резкое снижение переносимости нагрузки требуют стационара.","diagnostics":"Подтверждение структурных изменений — КТ высокого разрешения. Посев мокроты и оценка причины; функция дыхания по возрасту. Новая локальная симптоматика требует исключения обструкции.","treatment":"Индивидуальная техника очищения дыхательных путей и лечение обострения с учётом прежних посевов. Длительные антибиотики и ингаляционные средства определяет специалист; ГКС не являются универсальной терапией бронхоэктазов.","routing":"Пульмонологическое наблюдение, вакцинация и контроль рецидивов. При кровохарканье перейти к соответствующему экстренному алгоритму.","scenario":"Повторные «бронхиты» с ежедневной мокротой и кровянистыми прожилками требуют проверки бронхоэктазов и их причины.","images":["КТ: симптом перстня и отсутствие нормального сужения бронхов","Схема индивидуальных методов очищения дыхательных путей"],"source":"bronchiectasis","pediatric":"У ребёнка искать причины хронического влажного кашля и раннего структурного повреждения. Режимы обследования и антибиотиков определяет детский пульмонолог."},{"id":"pleural-effusion","title":"Плевральный выпот","english":"Pleural effusion","ages":["adult","pediatric"],"group":"pleural","clinical":"Жидкость в плевральной полости может вызывать одышку, боль на вдохе и ослабление дыхания. Объём, скорость накопления и причина определяют клиническую значимость.","causes":[["Транссудат","Сердечная недостаточность, цирроз, нефротический синдром."],["Экссудат","Инфекция, опухоль, туберкулёз или воспалительное заболевание."],["Осложнённый выпот","Эмпиема, гемоторакс, хилоторакс."]],"danger":"Тяжёлая одышка, сепсис, травма с подозрением на кровь или выраженное смещение средостения требуют срочной оценки.","diagnostics":"УЗИ подтверждает жидкость и помогает безопасно планировать пункцию. При диагностическом заборе оценивают клеточный состав, биохимию и микробиологию; интерпретация зависит от клинического контекста.","treatment":"Лечить причину. Пункцию или дренирование проводят по показаниям с ультразвуковой навигацией и подготовленной командой. При инфицированном выпоте нужны антибиотики и оценка контроля очага.","routing":"Новый необъяснённый выпот — профильная диагностика. Эмпиема, значимая недостаточность или гемоторакс обычно требуют госпитализации.","scenario":"На фоне пневмонии сохраняется лихорадка и одностороннее ослабление дыхания. УЗИ помогает выявить плевральное осложнение.","images":["УЗИ свободного и осумкованного плеврального выпота","Схема транссудата и экссудата"],"source":"effusion","pediatric":"У детей важна связь с пневмонией. Вопрос дренирования решают совместно с педиатрической и хирургической командами; взрослые объёмы и критерии процедуры не копируют."},{"id":"pulmonary-edema","title":"Отёк лёгких","english":"Pulmonary edema","ages":["adult","pediatric"],"group":"critical","clinical":"Жидкость в интерстиции и альвеолах нарушает газообмен. При кардиогенном отёке часты ортопноэ, влажные хрипы и признаки застоя; возможны гипертензия, ишемия или аритмия.","causes":[["Кардиогенный механизм","Острая дисфункция левого желудочка, клапанное поражение или перегрузка."],["Некардиогенный механизм","ОРДС, ингаляционное повреждение, другие причины повышенной проницаемости."],["Похожие состояния","Пневмония, обструкция, альвеолярное кровотечение."]],"danger":"Истощение, гипоксемия, пенистая мокрота, шок или ишемическая боль требуют немедленной помощи.","diagnostics":"ЭКГ, УЗИ сердца и лёгких, рентгенография; функция почек, электролиты и маркеры по предполагаемому триггеру. B-линии не являются специфичными только для сердечной недостаточности.","treatment":"Положение по переносимости, кислород при гипоксемии, ранняя оценка НИВ при подходящей клинике. Диуретик при застое; вазодилататор зависит от давления и противопоказаний. При шоке тактика иная, рутинный большой болюс жидкости может ухудшить состояние.","routing":"Острая декомпенсация — стационар с мониторингом; шок или потребность в вентиляции — ОРИТ. Устранить причину, а не только снизить выраженность хрипов.","scenario":"Ортопноэ, гипертензия и двусторонние B-линии: какие действия поддержат дыхание и как оценить гемодинамику?","images":["Сравнение кардиогенного и некардиогенного отёка","УЗИ B-линий и рентгенологические признаки застоя"],"source":"edema","pediatric":"У ребёнка учитывать врождённый порок, миокардит и перегрузку жидкостью. Решения о диуретике и гемодинамической поддержке принимают по массе и причине с педиатрической командой."},{"id":"pneumothorax","title":"Пневмоторакс","english":"Pneumothorax","ages":["adult","pediatric"],"group":"pleural","clinical":"Воздух в плевральной полости вызывает частичный или полный коллапс лёгкого. Возможны внезапная односторонняя боль, одышка и ослабление дыхания; при вторичном процессе резерв лёгких ниже.","causes":[["Первичный спонтанный","Без известной предшествующей болезни лёгких."],["Вторичный / травматический","Фоновая болезнь, травма, процедура или положительное давление."],["Напряжённый","Нарушение гемодинамики вследствие нарастающего внутриплеврального давления."]],"danger":"Подозрение на напряжённый пневмоторакс при дыхательном и циркуляторном ухудшении требует немедленного действия; не ждать снимка.","diagnostics":"У стабильного пациента — рентгенография или УЗИ подготовленным специалистом. Отсутствие скольжения плевры имеет и другие причины. Оценить симптомы, фоновые заболевания и тип пневмоторакса.","treatment":"При напряжённом варианте — экстренная декомпрессия обученной командой с последующим дренированием по протоколу. У стабильных пациентов наблюдение, аспирация или дренирование выбираются индивидуально; размер снимка не единственный критерий.","routing":"Нестабильность, травма, вторичный процесс или необходимость вмешательства — стационар. Перед выпиской обязательны контроль, признаки повторного обращения и ограничения полётов/дайвинга по профильным рекомендациям.","scenario":"На ИВЛ внезапно выросло давление в дыхательных путях, упала сатурация и давление; справа дыхание резко ослабло. Визуализация не должна задерживать помощь.","images":["Рентгенограмма с линией висцеральной плевры","УЗИ: скольжение плевры, lung point и диагностические ограничения"],"source":"pneumothorax","pediatric":"Возраст, размеры тела и состояние ребёнка определяют оборудование и место вмешательства. Для новорождённых предусмотрен отдельный маршрут."},{"id":"pulmonary-embolism","title":"Тромбоэмболия лёгочной артерии","english":"Pulmonary embolism","ages":["adult"],"group":"vascular","clinical":"ТЭЛА может проявляться внезапной одышкой, болью на вдохе, тахикардией, синкопе или кровохарканьем. Риск повышают тромбоз, операция, иммобилизация, рак, беременность и послеродовый период.","causes":[["Нестабильная ТЭЛА","Обструктивный шок или стойкая гипотензия."],["Стабильное подозрение","Сначала оценить клиническую вероятность."],["Похожие состояния","ОКС, пневмоторакс, пневмония, расслоение аорты."]],"danger":"Шок, обморок с ухудшением и выраженная гипоксемия требуют немедленной командной оценки.","diagnostics":"У стабильных взрослых использовать валидированный диагностический маршрут: клиническая вероятность, D-димер при подходящей вероятности, затем КТ-ангиография или альтернативная визуализация. PERC применим лишь к отобранным пациентам очень низкого риска.","treatment":"Поддержка дыхания и гемодинамики. Антикоагуляция зависит от вероятности, задержки диагностики и риска кровотечения. Реперфузия при высоком риске — решение специализированной команды; не назначать тромболизис только по наличию эмбола на КТ.","routing":"После подтверждения оценить ранний риск и условия наблюдения; амбулаторное лечение подходит только тщательно отобранным низкорисковым пациентам.","scenario":"После операции появилась новая одышка и тахикардия. Отрицательный снимок грудной клетки не исключает ТЭЛА.","images":["КТ-ангиограмма с дефектом наполнения","Схема диагностического маршрута по вероятности ТЭЛА"],"source":"pe","pediatric":""},{"id":"nonthrombotic-embolism","title":"Нетромботическая эмболия лёгких","english":"Nonthrombotic pulmonary embolism","ages":["adult"],"group":"vascular","clinical":"Закупорка лёгочных сосудов возможна воздухом, жиром, инфицированным материалом или другими частицами. Связь с процедурой, переломом, инфекцией или родами определяет клиническую гипотезу.","causes":[["Жировая эмболия","После перелома длинной кости: гипоксемия, неврологические изменения, иногда петехии."],["Воздушная эмболия","Внезапное ухудшение при сосудистой процедуре или баротравме."],["Септическая / иная эмболия","Инфекция внутрисосудистого источника; возможны множественные очаги."]],"danger":"Внезапная гипоксемия, шок или нарушение сознания после соответствующего события — экстренная ситуация.","diagnostics":"История события, газы крови и направленная визуализация. При септическом механизме — посевы и поиск источника; при воздушной эмболии обсудить профильный центр.","treatment":"Прекратить поступление эмболического материала, обеспечить дыхательную и гемодинамическую поддержку. Антибиотики при септической эмболии; показания к гипербарической терапии оценивают отдельно. Антикоагуляция не является универсальным лечением всех нетромботических вариантов.","routing":"Острое органное нарушение — ОРИТ и привлечение профильной команды. Тактика зависит от типа эмбола, а не переносится из стандартного маршрута тромботической ТЭЛА.","scenario":"Через сутки после перелома бедра возникли гипоксемия и спутанность. Нужно оценить жировую эмболию и альтернативные причины.","images":["Схема разновидностей нетромботических эмболов","КТ-примеры септических эмболов с подписями"],"source":"nonthrombotic","pediatric":""},{"id":"pulmonary-hypertension","title":"Лёгочная гипертензия и лёгочное сердце","english":"Pulmonary hypertension and cor pulmonale","ages":["adult"],"group":"vascular","clinical":"Повышенная нагрузка на правый желудочек проявляется одышкой при нагрузке, утомляемостью, обмороками и позднее отёками. Лёгочное сердце связано с заболеванием лёгких или лёгочного сосудистого русла.","causes":[["Левосердечная причина","Заболевание левого желудочка или клапанов."],["Лёгочная / гипоксическая причина","Хроническая болезнь лёгких и гипоксия."],["Сосудистая причина","Лёгочная артериальная гипертензия или хроническая тромбоэмболическая болезнь."]],"danger":"Обморок, шок, быстро нарастающие отёки и гипоксемия могут означать декомпенсацию правого желудочка.","diagnostics":"Эхокардиография оценивает вероятность, но гемодинамическое подтверждение и классификация обычно требуют катетеризации правых отделов. Обследование ищет обратимые и тромбоэмболические причины.","treatment":"Лечить причину и гипоксемию; объём жидкости и диуретики подбирать по гемодинамике. Специфические лёгочные вазодилататоры назначает профильный центр. Не прерывать жизненно важную инфузию простациклина без немедленной замены.","routing":"Подозрение — специализированное направление. Декомпенсация — ОРИТ с опытом ведения правожелудочковой недостаточности.","scenario":"У пациента с известной лёгочной гипертензией возникли синкопе и гипотензия: требуется оценка правого желудочка и причины декомпенсации.","images":["Схема групп лёгочной гипертензии","Эхо-признаки перегрузки правого желудочка"],"source":"ph","pediatric":""},{"id":"pneumonia-adult","title":"Пневмония у взрослых","english":"Pneumonia","ages":["adult"],"group":"infection","clinical":"Лихорадка, кашель, одышка и фокальные признаки поддерживают диагноз; у пожилых возможны спутанность и слабость без высокой температуры. Тяжесть оценивают отдельно от выраженности снимка.","causes":[["Внебольничная инфекция","Начало вне стационара; уточнить сопутствующие болезни."],["Аспирация / госпитальная инфекция","Другой спектр риска и выбор антибиотика."],["Похожие состояния","ТЭЛА, отёк, опухолевая обструкция, туберкулёз."]],"danger":"Гипоксемия, гипотензия, спутанность, выраженное тахипноэ или невозможность принимать жидкость требуют срочной стационарной оценки.","diagnostics":"Пульсоксиметрия, снимок по клинике и условиям оказания помощи; анализы и микробиология по тяжести. CRB-65/CURB-65 помогают, но не заменяют оценку кислорода, коморбидности и социальных условий.","treatment":"Начать подходящий антибиотик при установленной бактериальной пневмонии; выбор учитывает тяжесть, аллергию, функцию почек, местную резистентность и риск аспирации. Кислород и лечение сепсиса по показаниям. При улучшении пересмотреть внутривенный путь и длительность.","routing":"Гипоксемия, осложнения или небезопасное домашнее наблюдение — госпитализация. При отсутствии ожидаемого улучшения искать выпот, абсцесс, резистентность или альтернативный диагноз.","scenario":"Пожилой пациент спутан, кашляет и плохо пьёт, температура невысокая. Отсутствие высокой лихорадки не исключает тяжёлую пневмонию.","images":["Рентгенограмма долевой консолидации и воздушной бронхограммы","УЗИ консолидации и парапневмонического выпота"],"source":"pneumonia","pediatric":""},{"id":"pneumonia-children","title":"Пневмония у детей","english":"Pneumonia in children","ages":["pediatric"],"group":"infection","clinical":"Кашель и лихорадка с тахипноэ, втяжениями или локальными хрипами требуют оценки пневмонии. У младенца важны кормление, апноэ и активность. Свист не исключает инфекцию, но расширяет дифференциальный диагноз.","causes":[["Неосложнённая инфекция","Сохранены оксигенация, питьё и активность."],["Тяжёлая пневмония","Гипоксемия, выраженная работа дыхания, системное ухудшение."],["Осложнение","Плевральный выпот, эмпиема, некротизирующее поражение."]],"danger":"Апноэ, цианоз, истощение, вялость, плохая перфузия и стойкая гипоксемия — немедленная помощь.","diagnostics":"Диагноз часто клинический. Рутинный снимок не обязателен каждому стабильному ребёнку; он нужен при тяжёлом, осложнённом или нетипичном течении. УЗИ полезно при подозрении на выпот.","treatment":"Поддержать дыхание и гидратацию. Антибиотик при предполагаемой бактериальной пневмонии выбирают по возрасту, тяжести и локальному протоколу; не переносить взрослую дозу. Для тяжёлого течения открыть отдельную подробную страницу.","routing":"Госпитализация при кислородной потребности, обезвоживании, осложнениях и сомнительной возможности наблюдения. При ухудшении повторная оценка немедленная, а не только после окончания курса.","scenario":"Ребёнок с лихорадкой почти перестал пить и дышит с втяжениями. Решение о стационаре нельзя основывать только на наличии снимка.","images":["Возрастные признаки дыхательного усилия при пневмонии","Рентгенография и УЗИ при парапневмоническом выпоте"],"source":"pediatric-pneumonia","pediatric":""},{"id":"lung-abscess","title":"Абсцесс лёгкого","english":"Lung abscess","ages":["adult","pediatric"],"group":"infection","clinical":"Некротическая полость в лёгком может сопровождаться затяжной лихорадкой, продуктивным кашлем, неприятным запахом мокроты, потерей массы или кровохарканьем.","causes":[["Аспирация","Дисфагия, нарушенное сознание, болезни полости рта."],["Обструкция / инфекция","Инородное тело, опухоль, некротизирующая пневмония."],["Похожие полости","Туберкулёз, грибковое поражение, распадающаяся опухоль."]],"danger":"Сепсис, дыхательная недостаточность, кровотечение или прорыв в плевру требуют срочного стационара.","diagnostics":"Рентгенография; КТ уточняет полость и отличает её от эмпиемы. Посевы и направленная микробиология по рискам. При подозрении на обструкцию — оценка для бронхоскопии.","treatment":"Антибиотик с учётом вероятного спектра, аспирации и микробиологии; обеспечить оценку глотания и причину аспирации. Длительность зависит от клинического и рентгенологического ответа. Дренирование или хирургия нужны отдельным пациентам при неэффективности лечения или осложнениях.","routing":"Обычно требуется профильная стационарная оценка и длительное наблюдение до разрешения. Отсутствие ответа — повод пересмотреть диагноз и контроль очага.","scenario":"После эпизода аспирации сохраняются лихорадка и полость с уровнем жидкости. Нужно оценить абсцесс и исключить эмпиему.","images":["КТ полости с уровнем жидкости","Сравнение абсцесса лёгкого, эмпиемы и каверны"],"source":"abscess","pediatric":"У детей чаще рассматривают осложнение инфекции и аспирацию инородного тела. Инвазивные решения принимают с детским пульмонологом и хирургом."},{"id":"common-cold","title":"ОРВИ и простуда","english":"Common cold","ages":["adult","pediatric"],"group":"infection","clinical":"Ринорея, заложенность, боль в горле и кашель при сохранном общем состоянии чаще соответствуют вирусной инфекции верхних дыхательных путей. Оценить риск гриппа и COVID-19, если это влияет на раннее лечение.","causes":[["Неосложнённая вирусная инфекция","Преимущественно носоглоточные симптомы без дистресса."],["Грипп / COVID-19","Системные симптомы, эпидемиологический контакт и факторы риска."],["Осложнение / иной диагноз","Пневмония, отит, синусит, эпиглоттит по характерным признакам."]],"danger":"Затруднение дыхания, обезвоживание, спутанность, выраженная дисфагия или ухудшение после начального улучшения требуют пересмотра.","diagnostics":"При типичном лёгком течении лабораторные тесты и снимок обычно не нужны. Тест на вирус — если результат меняет противовирусную терапию или инфекционные меры.","treatment":"Питьё по переносимости, отдых, солевые средства для носа и симптоматическое обезболивание по показаниям. Антибиотики не лечат простуду. Проверять состав комбинированных средств, чтобы не дублировать действующие вещества.","routing":"Домашнее наблюдение при стабильности с правилами повторного обращения. Пациенты высокого риска нуждаются в ранней оценке противовирусной терапии при соответствующем диагнозе.","scenario":"Насморк и кашель при нормальном дыхании не являются самостоятельным показанием к антибиотику.","images":["Схема симптомов верхних и нижних дыхательных путей","Карточка признаков, при которых требуется повторный осмотр"],"source":"cold","pediatric":"Лихорадка у ребёнка младше 3 месяцев требует отдельной срочной оценки. Безрецептурные комбинированные средства от кашля и простуды не подходят маленьким детям."},{"id":"acute-bronchitis","title":"Острый бронхит","english":"Acute bronchitis","ages":["adult","pediatric"],"group":"infection","clinical":"Острый кашель после респираторной инфекции часто связан с вирусным бронхитом. Продуктивный кашель и окрашенная мокрота не доказывают необходимость антибиотика.","causes":[["Вирусный бронхит","Кашель без признаков пневмонии и тяжёлой системной болезни."],["Обструкция","Астма или ХОБЛ с бронхоспазмом."],["Иной диагноз","Пневмония, коклюш, аспирация, ТЭЛА по клинике."]],"danger":"Гипоксемия, высокая или стойкая лихорадка, фокальные признаки, кровохарканье и выраженная одышка требуют дополнительной оценки.","diagnostics":"Оценить жизненные показатели и лёгкие; снимок по подозрению на пневмонию. При приступообразном затяжном кашле и контакте рассмотреть коклюш.","treatment":"Симптоматическая помощь и исключение дыма. Рутинные антибиотики при неосложнённом бронхите не показаны. Бронходилататор используют при доказанном бронхоспазме, а не при любом кашле.","routing":"Амбулаторное наблюдение при стабильности. Объяснить, что кашель может сохраняться после исчезновения других симптомов; ухудшение требует повторного осмотра.","scenario":"У взрослого неделю кашель с зелёной мокротой, но показатели и аускультация спокойные. Цвет мокроты не определяет выбор антибиотика.","images":["Дифференциальная схема «бронхит — пневмония — обструкция»","Пример нормального снимка и очаговой консолидации"],"source":"bronchitis","pediatric":"У младенца оценить бронхиолит; при повторном свисте у дошкольника — возрастную астму. Слово «бронхит» не должно скрывать аспирацию или хронический влажный кашель."},{"id":"influenza","title":"Грипп","english":"Influenza","ages":["adult","pediatric"],"group":"infection","clinical":"Острое начало с лихорадкой, миалгией, головной болью и кашлем типично, но отсутствие температуры не исключает грипп. Беременность, младший возраст, пожилой возраст и хронические болезни повышают риск осложнений.","causes":[["Неосложнённый грипп","Респираторные и системные симптомы без органной недостаточности."],["Осложнение","Вирусная или вторичная бактериальная пневмония, декомпенсация хронической болезни."],["Похожие инфекции","COVID-19 и другие респираторные вирусы."]],"danger":"Одышка, боль в груди, гипоксемия, нарушение сознания, обезвоживание или повторное ухудшение требуют срочной оценки.","diagnostics":"Молекулярный тест предпочтителен, если результат влияет на ведение; отрицательный быстрый антигенный тест не всегда исключает инфекцию. Не задерживать показанное лечение тяжёлого или высокорискового пациента ради теста.","treatment":"Поддерживающая помощь и ранний противовирусный препарат по показаниям. Госпитализированным и высокорисковым пациентам лечение может быть полезно и после первых 48 часов. Антибиотик нужен при подозрении на бактериальное осложнение.","routing":"Стабильным — домашнее наблюдение и инфекционные меры; осложнённое течение — стационар. Сезонная вакцинация снижает риск последующих эпизодов.","scenario":"Беременная с характерными симптомами обращается на третий день. Прошедшие 48 часов не означают автоматического отказа от противовирусной терапии.","images":["Схема групп риска осложнённого гриппа","Визуальное сравнение неосложнённого течения и пневмонии"],"source":"flu","pediatric":"У детей выбор препарата и доза зависят от возраста, массы и функции почек. Аспирин при вирусной инфекции у детей не используют."},{"id":"tracheoesophageal-fistula","title":"Приобретённый трахеопищеводный свищ","english":"Acquired tracheoesophageal fistula","ages":["adult"],"group":"structural","clinical":"Сообщение между пищеводом и дыхательными путями вызывает кашель при глотании, повторную аспирацию, пневмонию и потерю массы. Возможна утечка воздуха у пациента на вентиляции.","causes":[["Ятрогенная / травматическая причина","Длительная интубация, повреждение манжетой, операции."],["Злокачественная причина","Опухоль пищевода или дыхательных путей."],["Другие повреждения","Инфекция, химическая травма или инородное тело."]],"danger":"Аспирация с дыхательной недостаточностью, сепсис или невозможность вентиляции требуют немедленной командной оценки.","diagnostics":"КТ и контрастное исследование, бронхоскопия и эндоскопия выбираются совместно с профильной командой. Не проводить пробное питьё при выраженном риске аспирации.","treatment":"Временно исключить небезопасный приём через рот, обеспечить дыхательную поддержку и альтернативное питание. Лечить инфекционное осложнение; закрытие, стентирование или хирургическую коррекцию планирует междисциплинарная команда.","routing":"Требуется торакальная хирургия, гастроэнтерология и пульмонология. Способ питания и защиты дыхательных путей фиксируют до перевода.","scenario":"После длительной интубации кашель появляется при каждом глотке и повторяются пневмонии. Это повод проверить патологическое сообщение.","images":["Анатомическая схема трахеопищеводного свища","Эндоскопический или контрастный пример с отмеченным сообщением"],"source":"fistula","pediatric":""},{"id":"preschool-asthma","title":"Астма у детей до 5 лет","english":"Asthma in children ≤ 5 years of age","ages":["pediatric"],"group":"obstructive","clinical":"Повторные эпизоды свиста, кашля и ограничения активности с ответом на бронходилататор поддерживают диагноз. Один вирусный эпизод свиста не равен установленной астме.","causes":[["Вариабельная обструкция","Повторные симптомы и наблюдаемый ответ на лечение."],["Бронхиолит / аспирация","Первый эпизод у младенца или внезапное начало."],["Другая причина","Хронический влажный кашель, плохая прибавка массы, фокальные изменения."]],"danger":"Выраженные втяжения, плохой поток, невозможность пить, истощение или изменение сознания — экстренная оценка.","diagnostics":"Диагноз преимущественно клинический с документированным ответом и повторной оценкой. Рутинные снимки не нужны; стандартная спирометрия обычно невыполнима у дошкольника.","treatment":"Препарат облегчения через дозированный ингалятор со спейсером и подходящей маской. При показаниях — пробный курс низкой дозы ингаляционного ГКС с заранее заданной оценкой ответа. Проверять технику и пересматривать диагноз, если эффекта нет.","routing":"Острый тяжёлый эпизод — стационар. Для долгосрочного ведения нужны обучение семьи, письменный план и контроль симптомов между инфекциями.","scenario":"Трёхлетний ребёнок повторно свистит при вирусных инфекциях, но между ними активен. Решение о базисной терапии зависит от частоты, тяжести и межприступных симптомов.","images":["Техника спейсера с маской у дошкольника","Схема оценки повторного свиста и пробной противовоспалительной терапии"],"source":"preschool","pediatric":""},{"id":"cyanosis","title":"Цианоз","english":"Cyanosis","ages":["adult","pediatric"],"group":"symptoms","clinical":"Синюшность слизистых больше соответствует центральному цианозу; холодные синюшные конечности могут отражать периферическую вазоконстрикцию. Внешний цвет недостаточен для оценки оксигенации.","causes":[["Гипоксемия","Заболевание лёгких, гиповентиляция или шунт."],["Нарушение перфузии","Шок, холод, периферический застой."],["Дисгемоглобинемия","Метгемоглобин или карбоксигемоглобин; обычная SpO₂ может вводить в заблуждение."]],"danger":"Внезапный центральный цианоз, апноэ, нарушение сознания или шок требуют немедленной оценки ABCDE.","diagnostics":"Проверить сигнал оксиметра, температуру конечности, дыхание и перфузию. По показаниям — газы крови с кооксиметрией, ЭКГ, визуализация и эхокардиография.","treatment":"Обеспечить оксигенацию и эффективную вентиляцию, лечить причину. Если кислород не даёт ожидаемого ответа, проверить шунт, дисгемоглобинемию и техническую ошибку; не ограничиваться повышением потока.","routing":"Новый центральный цианоз — срочный стационарный маршрут. Хронические индивидуальные цели сатурации учитывать только при известном установленном диагнозе.","scenario":"Синюшные губы сочетаются с необычным показанием пульсоксиметра после контакта с окислителем. Требуется оценка дисгемоглобинемии.","images":["Сравнение центрального и периферического цианоза","Схема ограничений пульсоксиметрии и роли кооксиметрии"],"source":"cyanosis","pediatric":"У новорождённого центральный цианоз требует отдельной срочной оценки, включая врождённый порок сердца. Не считать его обычным акроцианозом."},{"id":"neonatal-respiratory-distress","title":"Дыхательные нарушения у новорождённых","english":"Neonatal respiratory distress","ages":["pediatric"],"group":"neonatal","clinical":"Тахипноэ, стонущее дыхание, втяжения, апноэ и нарушение кормления у новорождённого имеют широкий круг причин. Учитывать срок гестации, обстоятельства родов и время появления симптомов.","causes":[["Лёгочные причины","Транзиторное тахипноэ, дефицит сурфактанта, аспирация, пневмоторакс."],["Инфекция / обмен","Сепсис, гипогликемия, гипотермия."],["Врождённая патология","Порок сердца, диафрагмальная грыжа, аномалия дыхательных путей."]],"danger":"Апноэ, брадикардия, центральный цианоз, шок и повторные десатурации требуют немедленной неонатальной помощи.","diagnostics":"Температура, глюкоза, пре- и постдуктальная сатурация по показаниям; газы крови, снимок и эхокардиография по клинике. Не задерживать поддержку ради обследования.","treatment":"Тепловая защита, обеспечение проходимости и дыхательная поддержка по неонатальному протоколу. Настройки и кислород подбирают по гестации и времени после рождения. При подозрении на сепсис или врождённый порок — немедленная профильная тактика.","routing":"Новый дыхательный дистресс у новорождённого требует срочной неонатологической оценки; нестабильность — неонатальная ОРИТ.","scenario":"У новорождённого с тахипноэ снижена температура и появился отказ от кормления. Нельзя объяснять картину только адаптацией после родов.","images":["Примеры стонущего дыхания и втяжений у новорождённого","Схема различий основных неонатальных причин дистресса"],"source":"neonatal","pediatric":""}]');

